import Testing
import Foundation
@testable import PrettyQRCore

/// Fixtures generated by the real URKit 15.1 (see PLAN.md, phase 1). They pin
/// byte-for-byte compatibility with BCR-2020-005 implementations.
@Suite struct URKitInteropTests {
    struct Fixture: Codable {
        var messageLen: Int
        var seed: UInt64
        var messageHex: String
        var maxFragmentLen: Int
        var singlePart: String?
        var parts: [String]
        var seqLen: Int
    }

    func loadFixtures() throws -> [Fixture] {
        let url = try #require(Bundle.module.url(forResource: "urkit-interop", withExtension: "json", subdirectory: "Fixtures"))
        return try JSONDecoder().decode([Fixture].self, from: Data(contentsOf: url))
    }

    @Test func ourEncoderMatchesURKitPartStrings() throws {
        for fixture in try loadFixtures() {
            let message = try #require(toData(hex: fixture.messageHex))
            let ur = UR(bytes: message)
            let encoder = UREncoder(ur, maxFragmentLen: fixture.maxFragmentLen)
            #expect(encoder.seqLen == fixture.seqLen)
            if let single = fixture.singlePart {
                #expect(ur.string == single)
            }
            let ours = (0..<fixture.parts.count).map { _ in encoder.nextPart() }
            #expect(ours == fixture.parts, "message of \(fixture.messageLen) bytes")
        }
    }

    @Test func ourDecoderReadsURKitParts() throws {
        for fixture in try loadFixtures() {
            let message = try #require(toData(hex: fixture.messageHex))
            let decoder = ScanDecoder()
            var result: ScanResult?
            for part in fixture.parts {
                if case .completed(let r) = decoder.receive(part.uppercased()) { result = r; break }
            }
            #expect(result?.data == message, "message of \(fixture.messageLen) bytes")
        }
    }
}
